const ALL_TOPICS = [
  { name: "Food", emoji: "🍕" }, { name: "Philosophy", emoji: "🧠" },
  { name: "Space", emoji: "🚀" }, { name: "History", emoji: "📜" },
  { name: "Animals", emoji: "🦁" }, { name: "Psychology", emoji: "🪞" },
  { name: "Art", emoji: "🎨" }, { name: "Science", emoji: "🔬" },
  { name: "Geography", emoji: "🌍" }, { name: "Music", emoji: "🎵" },
  { name: "Technology", emoji: "💻" }, { name: "Literature", emoji: "📚" },
  { name: "Sports", emoji: "⚽" }, { name: "Nature", emoji: "🌿" },
  { name: "Economics", emoji: "📈" }
];

// --- STATE ---
let state = {
  selectedTopics: [],
  currentTopic: null,
  currentFact: null,
  currentSearch: null,
  feedback: null,
  settingsTopics: []
};

// --- STORAGE (localStorage since no chrome.storage) ---
function save(key, val) { localStorage.setItem(key, JSON.stringify(val)); }
function load(key, def) { try { const v = localStorage.getItem(key); return v ? JSON.parse(v) : def; } catch { return def; } }

// --- HELPERS ---
function show(id) {
  document.querySelectorAll(".screen").forEach(s => s.classList.remove("active"));
  document.getElementById(id).classList.add("active");
  window.scrollTo(0, 0);
}

function weightedSample(pool, weights, n) {
  const items = [...pool];
  const result = [];
  for (let i = 0; i < n && items.length; i++) {
    const total = items.reduce((s, t) => s + (weights[t] || 1), 0);
    let r = Math.random() * total;
    for (let j = 0; j < items.length; j++) {
      r -= weights[items[j]] || 1;
      if (r <= 0) { result.push(items.splice(j, 1)[0]); break; }
    }
  }
  return result;
}

function to24Hour(hour, minute, ampm) {
  let h = parseInt(hour);
  if (ampm === "AM" && h === 12) h = 0;
  if (ampm === "PM" && h !== 12) h += 12;
  return { hour: h, minute: parseInt(minute) };
}

function from24Hour(h) {
  const ampm = h >= 12 ? "PM" : "AM";
  const hour = h % 12 || 12;
  return { hour, ampm };
}

// --- SERVICE WORKER ---
if ("serviceWorker" in navigator) {
  navigator.serviceWorker.register("/sw.js").catch(console.error);
}

// --- NOTIFICATIONS ---
function checkNotifPermission() {
  if (!("Notification" in window)) return;
  if (Notification.permission === "default") {
    document.getElementById("notif-banner").style.display = "flex";
  }
}

document.getElementById("enable-notif").onclick = () => {
  Notification.requestPermission().then(p => {
    if (p === "granted") {
      document.getElementById("notif-banner").style.display = "none";
      scheduleNotification();
    }
  });
};

function scheduleNotification() {
  const settings = load("settings", { popupHour: 13, popupMinute: 0 });
  const now = new Date();
  const next = new Date();
  next.setHours(settings.popupHour, settings.popupMinute, 0, 0);
  if (next <= now) next.setDate(next.getDate() + 1);
  const delay = next.getTime() - now.getTime();
  setTimeout(() => {
    if (Notification.permission === "granted") {
      new Notification("☕ Take a Break!", {
        body: "Time to learn something new!",
        icon: "/icons/icon192.png"
      });
    }
    scheduleNotification();
  }, delay);
}

// --- ONBOARDING ---
const onboardGrid = document.getElementById("onboard-topics");
const onboardSubmit = document.getElementById("onboard-submit");

ALL_TOPICS.forEach(t => {
  const chip = document.createElement("div");
  chip.className = "topic-chip";
  chip.textContent = `${t.emoji} ${t.name}`;
  chip.onclick = () => {
    chip.classList.toggle("selected");
    const idx = state.selectedTopics.indexOf(t.name);
    idx === -1 ? state.selectedTopics.push(t.name) : state.selectedTopics.splice(idx, 1);
    onboardSubmit.disabled = state.selectedTopics.length < 2;
  };
  onboardGrid.appendChild(chip);
});

onboardSubmit.onclick = () => {
  const weights = {};
  state.selectedTopics.forEach(t => weights[t] = 1);
  save("onboarded", true);
  save("topicPool", state.selectedTopics);
  save("topicWeights", weights);
  save("settings", { popupHour: 13, popupMinute: 0 });
  save("history", []);
  showChooseScreen(state.selectedTopics, weights);
  if (Notification.permission === "granted") scheduleNotification();
};

// --- INIT ---
const onboarded = load("onboarded", false);
const topicPool = load("topicPool", []);
const topicWeights = load("topicWeights", {});

if (!onboarded || topicPool.length < 2) {
  show("screen-onboard");
} else {
  showChooseScreen(topicPool, topicWeights);
  if (Notification.permission === "granted") scheduleNotification();
}

// --- CHOOSE SCREEN ---
function showChooseScreen(pool, weights) {
  if (!pool || !weights) {
    showChooseScreen(load("topicPool", []), load("topicWeights", {}));
    return;
  }
  const picked = weightedSample(pool, weights, 2);
  const cards = document.getElementById("topic-cards");
  cards.innerHTML = "";
  picked.forEach(name => {
    const t = ALL_TOPICS.find(x => x.name === name);
    const card = document.createElement("div");
    card.className = "topic-card";
    card.innerHTML = `<div class="emoji">${t?.emoji || "🌟"}</div><div class="name">${name}</div>`;
    card.onclick = () => { state.currentTopic = name; loadFact(name); };
    cards.appendChild(card);
  });
  show("screen-choose");
}

document.getElementById("shuffle-topics").onclick = (e) => {
  e.preventDefault();
  showChooseScreen(load("topicPool", []), load("topicWeights", {}));
};

document.getElementById("open-settings").onclick = (e) => {
  e.preventDefault();
  openSettings();
};

// --- FACT LOADER ---
function loadFact(topic) {
  const history = load("history", []);
  const usedFacts = history.filter(h => h.topic === topic).map(h => h.fact);
  const pool = (FACTS[topic] || []).filter(f => !usedFacts.includes(f.fact));
  const available = pool.length > 0 ? pool : (FACTS[topic] || []);
  if (!available.length) { showChooseScreen(load("topicPool", []), load("topicWeights", {})); return; }
  const chosen = available[Math.floor(Math.random() * available.length)];
  state.currentFact = chosen.fact;
  state.currentSearch = chosen.searchQuery;
  state.feedback = null;
  history.push({ topic, fact: chosen.fact, timestamp: Date.now(), feedback: null });
  save("history", history.slice(-200));
  showFact(topic, chosen.fact);
}

function showFact(topic, fact) {
  const t = ALL_TOPICS.find(x => x.name === topic);
  document.getElementById("fact-topic-label").textContent = `${t?.emoji || ""} ${topic}`;
  document.getElementById("fact-text").textContent = fact;
  document.getElementById("btn-up").className = "feedback-btn";
  document.getElementById("btn-down").className = "feedback-btn";
  show("screen-fact");
}

// --- FEEDBACK ---
document.getElementById("btn-up").onclick = () => recordFeedback(1);
document.getElementById("btn-down").onclick = () => recordFeedback(-1);

function recordFeedback(val) {
  state.feedback = val;
  document.getElementById("btn-up").className = "feedback-btn" + (val === 1 ? " active-up" : "");
  document.getElementById("btn-down").className = "feedback-btn" + (val === -1 ? " active-down" : "");
  const weights = load("topicWeights", {});
  const topic = state.currentTopic;
  if (weights[topic] !== undefined) weights[topic] = Math.max(0.1, Math.min(5, weights[topic] + val * 0.5));
  const history = load("history", []);
  for (let i = history.length - 1; i >= 0; i--) {
    if (history[i].topic === topic && history[i].fact === state.currentFact) { history[i].feedback = val; break; }
  }
  save("topicWeights", weights);
  save("history", history);
}

// --- ACTIONS ---
document.getElementById("btn-learn-more").onclick = () => {
  window.open(`https://www.google.com/search?q=${encodeURIComponent(state.currentSearch || state.currentTopic)}`, "_blank");
};
document.getElementById("btn-another-fact").onclick = () => loadFact(state.currentTopic);
document.getElementById("btn-change-topic").onclick = () => showChooseScreen(load("topicPool", []), load("topicWeights", {}));

// --- SETTINGS ---
function openSettings() {
  checkNotifPermission();
  const pool = load("topicPool", []);
  const settings = load("settings", { popupHour: 13, popupMinute: 0 });
  const { hour, ampm } = from24Hour(settings.popupHour);
  document.getElementById("popup-hour").value = hour;
  document.getElementById("popup-minute").value = settings.popupMinute;
  document.getElementById("popup-ampm").value = ampm;

  const grid = document.getElementById("settings-topics");
  grid.innerHTML = "";
  ALL_TOPICS.forEach(t => {
    const chip = document.createElement("div");
    chip.className = "topic-chip" + (pool.includes(t.name) ? " selected" : "");
    chip.textContent = `${t.emoji} ${t.name}`;
    chip.onclick = () => {
      chip.classList.toggle("selected");
      const idx = pool.indexOf(t.name);
      idx === -1 ? pool.push(t.name) : pool.splice(idx, 1);
    };
    grid.appendChild(chip);
  });
  state.settingsTopics = pool;
  show("screen-settings");
}

document.getElementById("back-btn").onclick = () => {
  showChooseScreen(load("topicPool", []), load("topicWeights", {}));
};

document.getElementById("save-settings").onclick = () => {
  const pool = [...document.querySelectorAll("#settings-topics .topic-chip.selected")].map(c => c.textContent.replace(/^\S+\s/, '').trim());
  // Re-extract names properly
  const selectedNames = [];
  document.querySelectorAll("#settings-topics .topic-chip").forEach((chip, i) => {
    if (chip.classList.contains("selected")) selectedNames.push(ALL_TOPICS[i].name);
  });
  if (selectedNames.length < 2) { alert("Please select at least 2 topics."); return; }
  const hour = document.getElementById("popup-hour").value;
  const minute = document.getElementById("popup-minute").value;
  const ampm = document.getElementById("popup-ampm").value;
  const { hour: h, minute: m } = to24Hour(hour, minute, ampm);
  const existingWeights = load("topicWeights", {});
  const weights = {};
  selectedNames.forEach(t => weights[t] = existingWeights[t] || 1);
  save("topicPool", selectedNames);
  save("topicWeights", weights);
  save("settings", { popupHour: h, popupMinute: m });
  if (Notification.permission === "granted") scheduleNotification();
  const msg = document.getElementById("saved-msg");
  msg.style.display = "block";
  setTimeout(() => msg.style.display = "none", 2000);
};

document.getElementById("reset-btn").onclick = () => {
  if (confirm("Reset all topic weights and history?")) {
    const pool = load("topicPool", []);
    const weights = {};
    pool.forEach(t => weights[t] = 1);
    save("topicWeights", weights);
    save("history", []);
    alert("Reset complete!");
  }
};
